INSERT INTO tb_banco_questoes (area, materia, topico, enunciado, alternativa_a, alternativa_b, alternativa_c, alternativa_d, correta, explicacao) VALUES
('matematica', 'Matemática', 'Juros simples', 'Um capital de R$ 1.000,00 é aplicado a juros simples de 2% ao mês. Qual o montante após 5 meses?', 'R$ 1.050,00', 'R$ 1.100,00', 'R$ 1.200,00', 'R$ 1.010,00', 'B', 'J = C·i·t = 1000 × 0,02 × 5 = 100; M = C + J = 1000 + 100 = 1100.'),
('matematica', 'Matemática', 'Probabilidade', 'Ao lançar um dado de 6 faces, qual a probabilidade de obter um número par?', '1/6', '1/3', '1/2', '2/3', 'C', 'Há 3 números pares (2, 4, 6) em 6 possíveis: 3/6 = 1/2.'),
('matematica', 'Matemática', 'Geometria', 'Qual é a soma dos ângulos internos de um triângulo?', '90°', '180°', '270°', '360°', 'B', 'Em qualquer triângulo, a soma dos ângulos internos é sempre 180°.'),
('matematica', 'Matemática', 'Estatística', 'A média aritmética dos números 4, 8, 10 e 14 é:', '8', '9', '10', '36', 'B', '(4 + 8 + 10 + 14) ÷ 4 = 36 ÷ 4 = 9.'),
('linguagens', 'Português', 'Sintaxe', 'Qual é o sujeito da oração "Choveu bastante ontem à noite"?', 'Inexistente (oração sem sujeito)', 'Oculto', 'Indeterminado', 'Composto', 'A', 'Verbos que indicam fenômenos da natureza (chover, nevar, ventar) são impessoais e não têm sujeito.'),
('linguagens', 'Português', 'Coesão', '"Ele chegou, porém não avisou ninguém." A conjunção "porém" expressa relação de:', 'Causa', 'Adição', 'Oposição/adversidade', 'Conclusão', 'C', '"Porém" é uma conjunção adversativa, assim como "mas", "contudo" e "entretanto".'),
('linguagens', 'Português', 'Ortografia', 'Assinale o par de palavras parônimas (grafia e som parecidos, sentidos diferentes):', 'Cessão e sessão', 'Ação e reação', 'Bom e ótimo', 'Casa e lar', 'A', '"Cessão" (ato de ceder) e "sessão" (reunião, período) têm sons parecidos e grafias diferentes — clássico exemplo de parônimos.'),
('linguagens', 'Português', 'Sintaxe', 'No período "Quando eu chegar, te aviso", a oração "Quando eu chegar" é classificada como:', 'Subordinada substantiva', 'Subordinada adverbial temporal', 'Coordenada sindética', 'Subordinada adjetiva', 'B', 'Ela indica o TEMPO em que a ação principal ("te aviso") vai acontecer — por isso é adverbial temporal.'),
('humanas', 'História', 'História geral', 'A Segunda Guerra Mundial terminou oficialmente em que ano?', '1939', '1943', '1945', '1950', 'C', 'A guerra começou em 1939 e terminou em 1945, com a rendição da Alemanha e, depois, do Japão.'),
('humanas', 'História', 'Independências americanas', 'O processo de independência das colônias americanas, no século XVIII e XIX, foi influenciado principalmente por quais ideais?', 'Mercantilismo', 'Iluminismo e liberalismo', 'Feudalismo', 'Absolutismo', 'B', 'As ideias iluministas de liberdade individual e soberania popular inspiraram os movimentos de independência, incluindo o do Brasil.'),
('humanas', 'História', 'Brasil República', 'A Proclamação da República no Brasil ocorreu em que ano?', '1822', '1888', '1889', '1930', 'C', 'A República foi proclamada em 15 de novembro de 1889, pondo fim ao Império.'),
('humanas', 'História', 'História geral', 'O Renascimento, movimento cultural dos séculos XIV a XVI, teve origem em qual região?', 'Inglaterra', 'Itália', 'Alemanha', 'Rússia', 'B', 'O Renascimento surgiu nas cidades-estado italianas (Florença, Veneza, Roma), graças à riqueza do comércio e ao resgate da cultura clássica.'),
('humanas', 'Geografia', 'Cartografia', 'O Brasil está localizado predominantemente em quais hemisférios?', 'Norte e Ocidental', 'Sul e Ocidental', 'Sul e Oriental', 'Norte e Oriental', 'B', 'A maior parte do território brasileiro está abaixo da linha do Equador (Sul) e a oeste do Meridiano de Greenwich (Ocidental).'),
('humanas', 'Geografia', 'Brasil', 'Qual é a capital do Brasil?', 'Rio de Janeiro', 'São Paulo', 'Brasília', 'Salvador', 'C', 'Brasília é a capital federal desde 1960, quando substituiu o Rio de Janeiro.'),
('humanas', 'Geografia', 'Geografia urbana', 'O processo de concentração da população em áreas urbanas é chamado de:', 'Êxodo rural', 'Urbanização', 'Metropolização', 'Conurbação', 'B', 'Urbanização é o aumento da proporção de pessoas vivendo em cidades em relação ao campo.'),
('humanas', 'Geografia', 'Hidrografia', 'Qual rio é considerado o mais extenso do mundo em volume de água?', 'Nilo', 'Mississippi', 'Amazonas', 'Yangtzé', 'C', 'O rio Amazonas despeja no oceano mais água do que os dez maiores rios do mundo somados.'),
('natureza', 'Física', 'Unidades de medida', 'A unidade de medida de energia no Sistema Internacional é:', 'Newton', 'Joule', 'Watt', 'Ampère', 'B', 'O joule (J) mede energia e trabalho; newton mede força, watt mede potência e ampère mede corrente elétrica.'),
('natureza', 'Física', 'Eletricidade', 'Em um circuito elétrico, a potência pode ser calculada por:', 'P = U · i', 'P = U / i', 'P = U + i', 'P = U − i', 'A', 'A potência elétrica é o produto da tensão (U) pela corrente (i).'),
('natureza', 'Física', 'Cinemática', 'O que acontece com a velocidade de um corpo em Movimento Retilíneo Uniforme (MRU)?', 'Aumenta constantemente', 'Diminui constantemente', 'Permanece constante', 'Varia de forma aleatória', 'C', 'No MRU, por definição, a velocidade não muda ao longo do tempo (aceleração igual a zero).'),
('natureza', 'Física', 'Leis de Newton', 'A 3ª Lei de Newton (Ação e Reação) afirma que:', 'Força resultante nula mantém o corpo em repouso ou MRU', 'Para toda ação existe uma reação de mesma intensidade, mesma direção e sentido oposto', 'F = m · a', 'A energia não pode ser criada nem destruída', 'B', 'É a definição da 3ª Lei; as outras alternativas descrevem a 1ª Lei, a 2ª Lei e a conservação de energia.'),
('natureza', 'Química', 'Substâncias', 'Qual é a fórmula química da água?', 'CO₂', 'H₂O', 'O₂', 'NaCl', 'B', 'A água é formada por 2 átomos de hidrogênio e 1 de oxigênio: H₂O.'),
('natureza', 'Química', 'Estados físicos', 'Os estados físicos da matéria mais comuns são:', 'Sólido, líquido e gasoso', 'Quente e frio', 'Puro e misturado', 'Ácido e básico', 'A', 'São os três estados físicos fundamentais da matéria, definidos pela organização das partículas.'),
('natureza', 'Química', 'Estrutura atômica', 'O número atômico de um elemento representa:', 'O número de nêutrons', 'O número de prótons', 'A massa atômica', 'O número de elétrons na última camada', 'B', 'O número atômico (Z) é definido pelo número de prótons no núcleo e identifica o elemento na tabela periódica.'),
('natureza', 'Química', 'Reações químicas', 'Uma reação de combustão sempre envolve a presença de:', 'Água', 'Oxigênio', 'Nitrogênio', 'Hidrogênio', 'B', 'Combustão é a reação de um combustível com o oxigênio (comburente), liberando energia.'),
('natureza', 'Biologia', 'Fisiologia humana', 'Qual sistema do corpo humano é responsável pelo transporte de oxigênio e nutrientes?', 'Sistema nervoso', 'Sistema circulatório', 'Sistema digestório', 'Sistema respiratório', 'B', 'O sistema circulatório, por meio do sangue bombeado pelo coração, transporta oxigênio, nutrientes e outras substâncias pelo corpo.'),
('natureza', 'Biologia', 'Genética', 'O processo de divisão celular que origina os gametas (óvulos e espermatozoides) é chamado de:', 'Mitose', 'Meiose', 'Fecundação', 'Fagocitose', 'B', 'A meiose reduz o número de cromossomos pela metade, formando células-filhas geneticamente diferentes: os gametas.'),
('natureza', 'Biologia', 'Fisiologia humana', 'Qual é a função principal dos glóbulos brancos (leucócitos)?', 'Transportar oxigênio', 'Coagulação sanguínea', 'Defesa do organismo', 'Transportar nutrientes', 'C', 'Os leucócitos fazem parte do sistema imunológico, combatendo agentes infecciosos.'),
('natureza', 'Biologia', 'Ecologia', 'Em uma cadeia alimentar, os seres que produzem seu próprio alimento (ex.: plantas) são chamados de:', 'Consumidores primários', 'Decompositores', 'Produtores', 'Consumidores secundários', 'C', 'Produtores (como plantas e algas) realizam fotossíntese e formam a base de toda cadeia alimentar.');
INSERT INTO tb_banco_flashcards (area, materia, topico, frente, verso) VALUES
('matematica', 'Matemática', 'Função quadrática', 'Vértice da parábola', 'O vértice de y = ax² + bx + c tem coordenadas xᵥ = −b/2a e yᵥ = −Δ/4a.'),
('matematica', 'Matemática', 'Matemática financeira', 'Juros simples', 'J = C · i · t, onde C é o capital, i é a taxa (em decimal) e t é o tempo — o juro não incide sobre juros anteriores.'),
('matematica', 'Matemática', 'Razão e proporção', 'Razão e proporção', 'Razão é a divisão entre dois valores (a/b); proporção é a igualdade entre duas razões (a/b = c/d).'),
('matematica', 'Matemática', 'Geometria espacial', 'Volume do cilindro', 'V = π · r² · h, onde r é o raio da base e h é a altura.'),
('linguagens', 'Português', 'Coesão textual', 'Coesão textual', 'Conjunto de recursos linguísticos (conectivos, pronomes, sinônimos) que ligam as partes do texto, garantindo que ele faça sentido como um todo.'),
('linguagens', 'Português', 'Ortografia', 'Crase', 'Fusão da preposição "a" com o artigo feminino "a(s)", indicada pelo acento grave (à); usada antes de palavras femininas que admitem o artigo "a".'),
('linguagens', 'Português', 'Morfologia', 'Vozes verbais', 'Voz ativa: o sujeito pratica a ação ("O aluno escreveu o texto"). Voz passiva: o sujeito sofre a ação ("O texto foi escrito pelo aluno").'),
('linguagens', 'Português', 'Sintaxe', 'Tipos de sujeito', 'Simples (um núcleo), composto (dois ou mais núcleos), oculto/elíptico (não aparece, mas é identificável) e indeterminado (não se sabe quem é).'),
('humanas', 'História', 'História geral', 'Iluminismo', 'Movimento filosófico do século XVIII que defendia a razão, a liberdade individual e criticava o absolutismo — base ideológica das revoluções Francesa e Americana.'),
('humanas', 'História', 'Brasil República', 'Ditadura Militar no Brasil', 'Período de 1964 a 1985, marcado por repressão política e censura; o AI-5 (1968) suspendeu diversas garantias constitucionais.'),
('humanas', 'História', 'História geral', 'Primeira Guerra Mundial', 'Conflito de 1914 a 1918 entre a Tríplice Aliança e a Tríplice Entente; estopim: assassinato do arquiduque Francisco Ferdinando.'),
('humanas', 'História', 'Brasil República', 'Constituição de 1988', 'Conhecida como "Constituição Cidadã", marcou a redemocratização do Brasil após a ditadura militar, ampliando direitos sociais e políticos.'),
('humanas', 'Geografia', 'Meio ambiente', 'Camada de ozônio', 'Camada da atmosfera que filtra a radiação ultravioleta do Sol; afetada por gases CFC no passado, hoje em recuperação graças ao Protocolo de Montreal (1987).'),
('humanas', 'Geografia', 'Meio ambiente', 'Desertificação', 'Processo de degradação do solo em áreas áridas e semiáridas, causado por desmatamento, uso excessivo do solo e mudanças climáticas.'),
('humanas', 'Geografia', 'Geografia urbana', 'Conurbação', 'Fusão de duas ou mais cidades que crescem até formar uma mancha urbana contínua, como ocorre na Grande São Paulo.'),
('humanas', 'Geografia', 'Geopolítica', 'Zona Econômica Exclusiva (ZEE)', 'Faixa marítima de até 200 milhas náuticas a partir da costa, onde o país tem direitos exclusivos de exploração de recursos.'),
('natureza', 'Física', 'Eletricidade', 'Potência elétrica', 'P = U · i, onde P é a potência (watts), U é a tensão (volts) e i é a corrente (ampères).'),
('natureza', 'Física', 'Cinemática', 'Movimento Uniformemente Variado (MUV)', 'Movimento com aceleração constante; a velocidade varia de forma uniforme ao longo do tempo: v = v₀ + a·t.'),
('natureza', 'Física', 'Mecânica', 'Densidade', 'd = m / V, razão entre a massa de um corpo e o volume que ele ocupa.'),
('natureza', 'Física', 'Mecânica', 'Conservação de energia mecânica', 'Em um sistema sem atrito, a soma da energia cinética e potencial permanece constante ao longo do movimento.'),
('natureza', 'Química', 'Ligações químicas', 'Ligação covalente', 'Ligação química formada pelo compartilhamento de pares de elétrons entre dois ametais, como em H₂O e CO₂.'),
('natureza', 'Química', 'Estados físicos', 'Estados físicos da matéria', 'Sólido (forma e volume definidos), líquido (volume definido, forma variável) e gasoso (forma e volume variáveis).'),
('natureza', 'Química', 'Estrutura atômica', 'Número atômico (Z)', 'Número de prótons no núcleo de um átomo; identifica o elemento químico na tabela periódica.'),
('natureza', 'Química', 'Misturas', 'Misturas homogêneas e heterogêneas', 'Homogênea: uma única fase visível (ex.: água com sal dissolvido). Heterogênea: duas ou mais fases visíveis (ex.: água e óleo).'),
('natureza', 'Biologia', 'Genética', 'Meiose', 'Divisão celular que reduz o número de cromossomos pela metade, originando os gametas (óvulos e espermatozoides), geneticamente diferentes entre si.'),
('natureza', 'Biologia', 'Fisiologia humana', 'Sistema circulatório', 'Responsável por transportar sangue, oxigênio, nutrientes e hormônios pelo corpo, tendo o coração como órgão central de bombeamento.'),
('natureza', 'Biologia', 'Imunologia', 'Vacinas', 'Estimulam o sistema imunológico a produzir anticorpos contra um agente infeccioso, sem causar a doença, gerando memória imunológica.'),
('natureza', 'Biologia', 'Ecologia', 'Biodiversidade', 'Variedade de formas de vida (genes, espécies e ecossistemas) em um ambiente; quanto maior, mais resiliente tende a ser o ecossistema.');
